import { SOLAR, type IconName } from "@/lib/icons/solar-map";

export type { IconName };

// Official Solar icons (@solar-icons/react), same set and styles as the Flutter app:
// filled = SolarIconsBold -> "bold", default = SolarIconsOutline -> "outline".
// The map is generated by scripts/gen-solar-map.mjs. Names mirror Flutter's SolarIcons* members.
//
// weight (outline only): Solar's Outline paths are filled shapes, which read thin at small sizes.
// "medium"/"strong" add a hairline round-joined stroke in the icon's own colour on top of the official
// paths (no path data is edited). "regular" is the untouched official glyph.
const WEIGHT = {
  regular: "",
  medium: "[stroke:currentColor] [stroke-width:0.6px] [stroke-linejoin:round]",
  strong: "[stroke:currentColor] [stroke-width:1px] [stroke-linejoin:round]",
} as const;

export type IconWeight = keyof typeof WEIGHT;

export function Icon({
  name,
  className = "size-6",
  filled = false,
  weight = "medium",
}: {
  name: IconName;
  className?: string;
  filled?: boolean;
  weight?: IconWeight;
}) {
  const Glyph = SOLAR[name][filled ? "bold" : "outline"];
  const extra = filled ? "" : WEIGHT[weight];
  // The wrapper owns the size (className), the glyph fills it. Sizing the glyph itself via size="1em"
  // made every icon follow the parent's font-size and ignore size-* classes.
  return (
    <span className={`inline-flex shrink-0 items-center justify-center ${className}`.trim()} aria-hidden="true">
      <Glyph className={`size-full ${extra}`.trim()} size="100%" color="currentColor" />
    </span>
  );
}
